import { useCallback, useEffect, useMemo, useState, type CSSProperties } from 'react';
import {
  AlertTriangle, ArrowLeft, BarChart3, CheckCircle2, ClipboardCheck, Clock3,
  Eye, FileCheck2, FileText, Gauge, GitBranch, LayoutDashboard, ListChecks,
  Plus, RefreshCw, Search, ShieldCheck, Target, TrendingUp,
} from 'lucide-react';
import { useAuth } from '../auth/AuthProvider';
import { GovernedDecisionDialog, type DecisionFieldConfig } from '../components/GovernedDecisionDialog';
import { GovernanceCriteriaLinkage } from '../components/governance/GovernanceCriteriaLinkage';
import { ModuleHeader } from '../components/ModuleHeader';
import { StatusBadge } from '../components/StatusBadge';
import { useAsyncData } from '../hooks/useAsyncData';
import { useI18n } from '../i18n/I18nContext';
import { formatDate, humanize } from '../lib/format';
import { getDepartments, getProfiles } from '../lib/grcApi';
import type { GovernanceCriteriaLink } from '../lib/governanceCriteriaLinkageApi';
import { triggerGovernedDocumentReview } from '../lib/policySopApi';
import {
  createUi4Capa,
  createUi4CapaActionItem,
  getUi4CapaDetail,
  getUi4CapaRegister,
  runUi4CapaWorkflowAction,
  updateUi4CapaActionItem,
  type Ui4CapaActionItem,
  type Ui4CapaDetail,
  type Ui4CapaRecord,
} from '../lib/ui4AuditCapaApi';
import { evaluateUi4CapaClosure, ui4CapaProgress, ui4CapaStatusTone } from '../lib/ui4AuditCapaModel';

type CapaScreen = 'dashboard' | 'register' | 'detail' | 'plan' | 'implementation' | 'verification' | 'closure' | 'report' | 'analytics' | 'review';
type CapaAction = 'create' | 'assign' | 'submit_plan' | 'approve_plan' | 'reject_plan' | 'create_item' | 'update_item' | 'submit_completion' | 'validate_completion' | 'reject_completion' | 'start_effectiveness' | 'complete_effectiveness' | 'request_closure' | 'approve_closure' | 'reject_closure' | 'reopen' | 'refresh_inheritance' | 'document_review';

interface CapaDecision { action: CapaAction; capa?: Ui4CapaRecord; item?: Ui4CapaActionItem }

const emptyDetail: Ui4CapaDetail = { actions: [], events: [], effectivenessReviews: [], blocker: null, links: [] };
const capaScreens: Array<{ id: CapaScreen; label: string; icon: typeof LayoutDashboard }> = [
  { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
  { id: 'register', label: 'CAPA register', icon: ClipboardCheck },
  { id: 'detail', label: 'Details', icon: FileCheck2 },
  { id: 'plan', label: 'Plan', icon: ListChecks },
  { id: 'implementation', label: 'Implementation', icon: TrendingUp },
  { id: 'verification', label: 'Verification', icon: ShieldCheck },
  { id: 'closure', label: 'Closure', icon: CheckCircle2 },
  { id: 'report', label: 'Report', icon: FileText },
  { id: 'analytics', label: 'Analytics', icon: BarChart3 },
  { id: 'review', label: 'Review', icon: ClipboardCheck },
];

function EmptyCapa({ title, detail }: { title: string; detail?: string }) {
  return <div className="ui3-empty-state"><ClipboardCheck size={23} /><strong>{title}</strong>{detail ? <p>{detail}</p> : null}</div>;
}

function capaSourceLabel(value: string) {
  if (value === 'audit_finding') return 'Audit finding';
  if (value === 'compliance_assessment' || value === 'compliance_finding' || value === 'compliance_obligation') return 'Compliance';
  if (value === 'ovr') return 'OVR';
  if (value === 'risk') return 'Risk';
  return humanize(value);
}

function MiniBar({ label, value, max, tone = 'primary' }: { label: string; value: number; max: number; tone?: string }) {
  return <div className="ui4-mini-bar"><span>{label}</span><div><i className={`ui4-fill--${tone}`} style={{ width: `${max ? Math.max(4, (value / max) * 100) : 0}%` }} /></div><strong>{value}</strong></div>;
}

export function Capa() {
  const auth = useAuth();
  const { language } = useI18n();
  const text = useCallback((en: string, ar: string) => language === 'ar' ? ar : en, [language]);
  const [screen, setScreen] = useState<CapaScreen>('dashboard');
  const [records, setRecords] = useState<Ui4CapaRecord[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [detail, setDetail] = useState<Ui4CapaDetail>(emptyDetail);
  const [governanceLinks, setGovernanceLinks] = useState<GovernanceCriteriaLink[]>([]);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [sourceFilter, setSourceFilter] = useState('all');
  const [decision, setDecision] = useState<CapaDecision | null>(null);
  const [busy, setBusy] = useState(false);
  const [loading, setLoading] = useState(true);
  const [notice, setNotice] = useState<string | null>(null);
  const departments = useAsyncData(getDepartments, []);
  const profiles = useAsyncData(getProfiles, []);

  const canManage = auth.roles.some((role) => ['super_admin', 'governance_admin', 'compliance_officer', 'department_manager', 'division_head'].includes(role.role));
  const canReview = auth.roles.some((role) => ['super_admin', 'governance_admin', 'compliance_officer', 'auditor'].includes(role.role));
  const selected = records.find((record) => record.id === selectedId) ?? null;
  const closure = evaluateUi4CapaClosure(detail.blocker);

  const loadRegister = useCallback(async () => {
    setLoading(true);
    try {
      const rows = await getUi4CapaRegister();
      setRecords(rows);
      setSelectedId((current) => current && rows.some((row) => row.id === current) ? current : rows[0]?.id ?? null);
    } catch (error) {
      setNotice(error instanceof Error ? error.message : text('CAPA register is unavailable.', 'سجل الإجراءات التصحيحية غير متاح.'));
    } finally { setLoading(false); }
  }, [text]);

  const loadDetail = useCallback(async (capaId: string) => {
    try { setDetail(await getUi4CapaDetail(capaId)); }
    catch (error) { setNotice(error instanceof Error ? error.message : text('CAPA detail is unavailable.', 'تفاصيل الإجراء التصحيحي غير متاحة.')); }
  }, [text]);

  useEffect(() => { void loadRegister(); }, [loadRegister]);
  useEffect(() => { if (selectedId) void loadDetail(selectedId); else setDetail(emptyDetail); }, [loadDetail, selectedId]);

  const filtered = useMemo(() => records.filter((record) => {
    const query = search.trim().toLowerCase();
    return (!query || `${record.capa_code ?? ''} ${record.capa_title} ${record.capa_description ?? ''}`.toLowerCase().includes(query))
      && (statusFilter === 'all' || record.capa_status === statusFilter)
      && (sourceFilter === 'all' || record.source_type === sourceFilter);
  }), [records, search, sourceFilter, statusFilter]);

  function openRecord(record: Ui4CapaRecord, target: CapaScreen = 'detail') {
    setSelectedId(record.id);
    setScreen(target);
    setGovernanceLinks([]);
  }

  async function refresh() {
    await loadRegister();
    if (selectedId) await loadDetail(selectedId);
  }

  async function executeDecision(values: Record<string, unknown>) {
    if (!decision) return;
    setBusy(true);
    try {
      if (decision.action === 'create') await createUi4Capa({
        capa_title: String(values.capa_title || ''), capa_description: String(values.capa_description || ''),
        capa_type: String(values.capa_type || 'corrective_action'), source_type: String(values.source_type || 'other'),
        source_id: String(values.source_id || '') || null, source_reference: String(values.source_reference || '') || null,
        department_id: String(values.department_id || '') || null, capa_owner_id: String(values.capa_owner_id || '') || null,
        priority_level: String(values.priority_level || '') || null, severity_level: String(values.severity_level || '') || null,
        root_cause_summary: String(values.root_cause_summary || '') || null, due_date: String(values.due_date || '') || null,
        evidence_required: true, validation_required: true, effectiveness_review_required: true,
      });
      const capa = decision.capa;
      if (capa) {
        const payload = { note: String(values.note || '') || null };
        if (decision.action === 'assign') await runUi4CapaWorkflowAction('ui4_assign_capa', capa.id, { owner_id: String(values.owner_id || '') || null, ...payload });
        if (decision.action === 'submit_plan') await runUi4CapaWorkflowAction('ui4_submit_capa_plan', capa.id, payload);
        if (decision.action === 'approve_plan') await runUi4CapaWorkflowAction('ui4_approve_capa_plan', capa.id, payload);
        if (decision.action === 'reject_plan') await runUi4CapaWorkflowAction('ui4_reject_capa_plan', capa.id, { reason: String(values.reason || ''), ...payload });
        if (decision.action === 'create_item') await createUi4CapaActionItem(capa.id, {
          action_item_title: String(values.action_item_title || ''), action_item_description: String(values.action_item_description || '') || null,
          action_owner_id: String(values.action_owner_id || '') || null, priority_level: String(values.priority_level || '') || null,
          due_date: String(values.due_date || '') || null, evidence_required: String(values.evidence_required || 'false') === 'true',
        });
        if (decision.action === 'update_item' && decision.item) await updateUi4CapaActionItem(decision.item.id, String(values.status || 'in_progress'), String(values.note || ''));
        if (decision.action === 'submit_completion') await runUi4CapaWorkflowAction('ui4_submit_capa_completion', capa.id, payload);
        if (decision.action === 'validate_completion') await runUi4CapaWorkflowAction('ui4_validate_capa_completion', capa.id, payload);
        if (decision.action === 'reject_completion') await runUi4CapaWorkflowAction('ui4_reject_capa_completion', capa.id, { reason: String(values.reason || ''), ...payload });
        if (decision.action === 'start_effectiveness') await runUi4CapaWorkflowAction('ui4_start_capa_effectiveness', capa.id, { review_due_date: String(values.review_due_date || '') || null, review_method: String(values.review_method || '') || null });
        if (decision.action === 'complete_effectiveness') await runUi4CapaWorkflowAction('ui4_complete_capa_effectiveness', capa.id, { review_id: String(values.review_id || ''), review_result: String(values.review_result || 'effective'), note: String(values.note || '') || null });
        if (decision.action === 'request_closure') await runUi4CapaWorkflowAction('ui4_request_capa_closure', capa.id, payload);
        if (decision.action === 'approve_closure') await runUi4CapaWorkflowAction('ui4_approve_capa_closure', capa.id, payload);
        if (decision.action === 'reject_closure') await runUi4CapaWorkflowAction('ui4_reject_capa_closure', capa.id, { reason: String(values.reason || ''), ...payload });
        if (decision.action === 'reopen') await runUi4CapaWorkflowAction('ui4_reopen_capa', capa.id, { reason: String(values.reason || '') });
        if (decision.action === 'refresh_inheritance') await runUi4CapaWorkflowAction('ui4_refresh_capa_inheritance', capa.id, {});
        if (decision.action === 'document_review') await triggerGovernedDocumentReview({
          document_id: String(values.document_id || ''), trigger_type: 'capa', source_entity_type: 'capa', source_entity_id: capa.id,
          due_date: String(values.due_date || '') || undefined, trigger_note: String(values.note || '') || undefined,
        });
      }
      setNotice(text('Governed CAPA action recorded.', 'تم تسجيل إجراء تصحيحي محكوم.'));
      await refresh();
    } finally { setBusy(false); }
  }

  const profileOptions = [{ value: '', label: text('Select owner', 'اختر المالك') }, ...(profiles.data ?? []).map((profile) => ({ value: profile.id, label: language === 'ar' ? profile.full_name_ar || profile.full_name_en : profile.full_name_en }))];
  const decisionFields = useMemo<DecisionFieldConfig[]>(() => {
    if (!decision) return [];
    if (decision.action === 'create') return [
      { id: 'capa_title', label: text('CAPA title', 'عنوان الإجراء التصحيحي'), type: 'text', required: true, autoFocus: true },
      { id: 'capa_description', label: text('Problem statement', 'بيان المشكلة'), type: 'textarea', required: true },
      { id: 'capa_type', label: text('Type', 'النوع'), type: 'select', defaultValue: 'corrective_action', options: ['correction','corrective_action','preventive_action','improvement_action','containment_action','effectiveness_action'].map((value) => ({ value, label: humanize(value, language) })) },
      { id: 'source_type', label: text('Source', 'المصدر'), type: 'select', defaultValue: 'other', options: ['other','audit_finding','risk','ovr','compliance_assessment','compliance_finding','compliance_obligation'].map((value) => ({ value, label: capaSourceLabel(value) })) },
      { id: 'source_id', label: text('Source record ID', 'معرف سجل المصدر'), type: 'text' },
      { id: 'source_reference', label: text('Source reference', 'مرجع المصدر'), type: 'text' },
      { id: 'department_id', label: text('Department', 'الإدارة'), type: 'select', options: [{ value: '', label: text('Select department', 'اختر الإدارة') }, ...(departments.data ?? []).map((department) => ({ value: department.id, label: language === 'ar' ? department.name_ar || department.name_en : department.name_en }))] },
      { id: 'capa_owner_id', label: text('Owner', 'المالك'), type: 'select', options: profileOptions },
      { id: 'priority_level', label: text('Priority', 'الأولوية'), type: 'select', defaultValue: 'medium', options: ['critical','high','medium','low'].map((value) => ({ value, label: humanize(value, language) })) },
      { id: 'root_cause_summary', label: text('Root cause summary', 'ملخص السبب الجذري'), type: 'textarea' },
      { id: 'due_date', label: text('Target date', 'التاريخ المستهدف'), type: 'date' },
    ];
    if (decision.action === 'assign') return [{ id: 'owner_id', label: text('CAPA owner', 'مالك الإجراء التصحيحي'), type: 'select', options: profileOptions, required: true }, { id: 'note', label: text('Assignment note', 'ملاحظة الإسناد'), type: 'textarea' }];
    if (decision.action === 'create_item') return [
      { id: 'action_item_title', label: text('Action title', 'عنوان الإجراء'), type: 'text', required: true, autoFocus: true },
      { id: 'action_item_description', label: text('Description', 'الوصف'), type: 'textarea' },
      { id: 'action_owner_id', label: text('Action owner', 'مالك الإجراء'), type: 'select', options: profileOptions },
      { id: 'priority_level', label: text('Priority', 'الأولوية'), type: 'select', defaultValue: 'medium', options: ['high','medium','low'].map((value) => ({ value, label: humanize(value, language) })) },
      { id: 'due_date', label: text('Due date', 'تاريخ الاستحقاق'), type: 'date' },
      { id: 'evidence_required', label: text('Evidence required', 'الدليل مطلوب'), type: 'select', defaultValue: 'true', options: [{ value: 'true', label: text('Yes', 'نعم') }, { value: 'false', label: text('No', 'لا') }] },
    ];
    if (decision.action === 'update_item') return [{ id: 'status', label: text('Action status', 'حالة الإجراء'), type: 'select', defaultValue: decision.item?.status || 'in_progress', options: ['open','assigned','in_progress','blocked','evidence_required','completed','rejected','cancelled'].map((value) => ({ value, label: humanize(value, language) })) }, { id: 'note', label: text('Progress note', 'ملاحظة التقدم'), type: 'textarea', required: true }];
    if (['reject_plan','reject_completion','reject_closure','reopen'].includes(decision.action)) return [{ id: 'reason', label: text('Required reason', 'السبب المطلوب'), type: 'textarea', required: true, autoFocus: true }, { id: 'note', label: text('Reviewer note', 'ملاحظة المراجع'), type: 'textarea' }];
    if (decision.action === 'start_effectiveness') return [{ id: 'review_due_date', label: text('Verification due date', 'تاريخ استحقاق التحقق'), type: 'date', required: true }, { id: 'review_method', label: text('Verification method', 'طريقة التحقق'), type: 'textarea', required: true }];
    if (decision.action === 'complete_effectiveness') return [
      { id: 'review_id', label: text('Effectiveness review', 'مراجعة الفعالية'), type: 'select', options: detail.effectivenessReviews.map((review) => ({ value: review.id, label: `${formatDate(review.review_due_date)} · ${humanize(review.review_result, language)}` })), required: true },
      { id: 'review_result', label: text('Result', 'النتيجة'), type: 'select', defaultValue: 'effective', options: ['effective','ineffective','needs_more_time','repeated_issue_detected'].map((value) => ({ value, label: humanize(value, language) })) },
      { id: 'note', label: text('Verification conclusion', 'استنتاج التحقق'), type: 'textarea', required: true },
    ];
    if (decision.action === 'document_review') return [
      { id: 'document_id', label: text('Governed document', 'الوثيقة المحكومة'), type: 'select', options: governanceLinks.filter((link) => link.target_document_id).map((link) => ({ value: link.target_document_id || '', label: link.target_display_label || humanize(link.target_criterion_type, language) })), required: true },
      { id: 'due_date', label: text('Review due date', 'تاريخ استحقاق المراجعة'), type: 'date' },
      { id: 'note', label: text('Review trigger rationale', 'مبرر تشغيل المراجعة'), type: 'textarea', required: true },
    ];
    return [{ id: 'note', label: text('Decision rationale', 'مبرر القرار'), type: 'textarea', required: true, autoFocus: true }];
  }, [decision, departments.data, detail.effectivenessReviews, governanceLinks, language, profileOptions, text]);

  const open = records.filter((record) => !['closed','cancelled'].includes(record.capa_status)).length;
  const overdue = records.filter((record) => record.overdue_flag || (record.due_date && new Date(record.due_date).getTime() < Date.now() && record.capa_status !== 'closed')).length;
  const closed = records.filter((record) => record.capa_status === 'closed').length;
  const sourceSummary = [...new Set(records.map((record) => record.source_type))].map((source) => ({ source, count: records.filter((record) => record.source_type === source).length })).sort((a, b) => b.count - a.count);
  const maxSource = Math.max(1, ...sourceSummary.map((item) => item.count));
  const prioritySummary = ['critical','high','medium','low'].map((priority) => ({ priority, count: records.filter((record) => record.priority_level === priority).length }));
  const maxPriority = Math.max(1, ...prioritySummary.map((item) => item.count));

  function CapaTable({ rows = filtered }: { rows?: Ui4CapaRecord[] }) {
    return <div className="ui3-data-table ui4-capa-table"><div className="ui3-table-head"><span>{text('CAPA', 'الإجراء التصحيحي')}</span><span>{text('Type', 'النوع')}</span><span>{text('Source', 'المصدر')}</span><span>{text('Owner', 'المالك')}</span><span>{text('Priority', 'الأولوية')}</span><span>{text('Due date', 'الاستحقاق')}</span><span>{text('Status', 'الحالة')}</span><span /></div>{rows.map((record) => <button type="button" className="ui3-table-row" key={record.id} onClick={() => openRecord(record)}><span><strong>{record.capa_code || 'CAPA'}</strong><small>{record.capa_title}</small></span><span>{humanize(record.capa_type, language)}</span><span>{capaSourceLabel(record.source_type)}</span><span>{record.capa_owner_name || text('Unassigned', 'غير مسند')}</span><span><span className={`ui3-pill ui3-tone--${record.priority_level === 'critical' || record.priority_level === 'high' ? 'danger' : record.priority_level === 'medium' ? 'warning' : 'success'}`}>{humanize(record.priority_level || 'not set', language)}</span></span><span>{formatDate(record.due_date)}</span><span><span className={`ui3-pill ui3-tone--${ui4CapaStatusTone(record.capa_status)}`}>{humanize(record.capa_status, language)}</span></span><span><Eye size={15} /></span></button>)}</div>;
  }

  return <section className="page-section ui3-module ui4-module" data-testid="ui4-capa">
    <ModuleHeader eyebrow={text('Corrective and preventive action', 'الإجراءات التصحيحية والوقائية')} title={text('CAPA', 'الإجراءات التصحيحية')} subtitle={text('Capture issues, inherit source governance truth, implement action, verify effectiveness, and close with evidence.', 'التقاط المشكلات ووراثة حقيقة حوكمة المصدر وتنفيذ الإجراءات والتحقق من الفعالية والإغلاق بالأدلة.')} action={canManage ? <button type="button" className="ui3-primary-button" onClick={() => setDecision({ action: 'create' })}><Plus size={16} />{text('New CAPA', 'إجراء تصحيحي جديد')}</button> : null} />
    <nav className="ui4-workspace-tabs" aria-label={text('CAPA workspace views', 'عروض مساحة عمل الإجراءات التصحيحية')}>{capaScreens.map((item) => { const Icon = item.icon; const recordRequired = !['dashboard','register','analytics'].includes(item.id); return <button type="button" key={item.id} aria-label={item.label} aria-current={screen === item.id ? 'page' : undefined} className={screen === item.id ? 'active' : ''} disabled={recordRequired && !selected} onClick={() => setScreen(item.id)}><Icon size={15} /><span>{item.label}</span></button>; })}</nav>
    {notice ? <div className="ui3-notice" role="status">{notice}</div> : null}

    {screen === 'dashboard' ? <div className="ui4-screen" data-testid="ui4-capa-dashboard"><div className="ui3-kpi-grid"><article><span>{text('Total CAPAs', 'إجمالي الإجراءات')}</span><strong>{records.length}</strong><small>{text('Visible in scope', 'ظاهرة في النطاق')}</small></article><article className="ui3-tone--success"><span>{text('Open', 'مفتوحة')}</span><strong>{open}</strong><small>{text('Active lifecycle', 'دورة حياة نشطة')}</small></article><article className="ui3-tone--warning"><span>{text('In progress', 'قيد التنفيذ')}</span><strong>{records.filter((record) => ['action_plan_approved','in_progress','evidence_required','completion_submitted'].includes(record.capa_status)).length}</strong><small>{text('Implementation underway', 'التنفيذ جارٍ')}</small></article><article className="ui3-tone--danger"><span>{text('Overdue', 'متأخرة')}</span><strong>{overdue}</strong><small>{text('Action required', 'إجراء مطلوب')}</small></article><article><span>{text('Closed', 'مغلقة')}</span><strong>{closed}</strong><small>{text('Evidence-backed', 'مدعومة بالأدلة')}</small></article></div><div className="ui3-dashboard-grid"><section className="ui3-surface"><div className="ui3-section-heading"><div><span>{text('CAPA trend', 'اتجاه الإجراءات')}</span><h2>{text('Lifecycle status', 'حالة دورة الحياة')}</h2></div><TrendingUp size={20} /></div><div className="ui4-sparkline" aria-label={text('CAPA lifecycle distribution', 'توزيع دورة حياة الإجراءات')}>{records.slice(0, 20).map((record, index) => <i key={record.id} style={{ height: `${25 + ((ui4CapaProgress(record) + index * 7) % 70)}%` }} />)}</div></section><section className="ui3-surface"><div className="ui3-section-heading"><div><span>{text('CAPA by source', 'الإجراءات حسب المصدر')}</span><h2>{text('Source portfolio', 'محفظة المصادر')}</h2></div><GitBranch size={20} /></div><div className="ui4-donut-layout"><div className="ui4-donut" style={{ '--ui4-progress': `${records.length ? (closed / records.length) * 360 : 0}deg` } as CSSProperties}><strong>{records.length}</strong><span>{text('Total', 'الإجمالي')}</span></div><div className="ui4-legend">{sourceSummary.slice(0, 5).map((item) => <span key={item.source}><i />{capaSourceLabel(item.source)} <b>{item.count}</b></span>)}</div></div></section><section className="ui3-surface ui3-span-all"><div className="ui3-section-heading"><div><span>{text('Priority queue', 'قائمة الأولويات')}</span><h2>{text('Top open CAPAs', 'أهم الإجراءات المفتوحة')}</h2></div><AlertTriangle size={20} /></div><div className="ui3-priority-grid">{records.filter((record) => record.capa_status !== 'closed').slice(0, 6).map((record) => <button type="button" key={record.id} onClick={() => openRecord(record)}><span className={`ui3-score-dot ui3-tone--${record.overdue_flag ? 'danger' : 'warning'}`}>{ui4CapaProgress(record)}</span><span><strong>{record.capa_title}</strong><small>{record.capa_code} · {formatDate(record.due_date)}</small></span><Eye size={16} /></button>)}</div></section></div></div> : null}

    {screen === 'register' ? <div className="ui4-screen" data-testid="ui4-capa-register"><div className="ui3-kpi-grid"><article><span>{text('All', 'الكل')}</span><strong>{records.length}</strong></article><article><span>{text('Open', 'مفتوحة')}</span><strong>{open}</strong></article><article className="ui3-tone--warning"><span>{text('In progress', 'قيد التنفيذ')}</span><strong>{records.filter((record) => ui4CapaProgress(record) > 20 && ui4CapaProgress(record) < 100).length}</strong></article><article className="ui3-tone--danger"><span>{text('Overdue', 'متأخرة')}</span><strong>{overdue}</strong></article><article className="ui3-tone--success"><span>{text('Closed', 'مغلقة')}</span><strong>{closed}</strong></article></div><section className="ui3-filter-bar"><label className="ui3-search"><Search size={16} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder={text('Search CAPAs', 'بحث الإجراءات التصحيحية')} /></label><select value={sourceFilter} onChange={(event) => setSourceFilter(event.target.value)}><option value="all">{text('All sources', 'كل المصادر')}</option>{[...new Set(records.map((record) => record.source_type))].map((value) => <option value={value} key={value}>{capaSourceLabel(value)}</option>)}</select><select value={statusFilter} onChange={(event) => setStatusFilter(event.target.value)}><option value="all">{text('All statuses', 'كل الحالات')}</option>{[...new Set(records.map((record) => record.capa_status))].map((value) => <option value={value} key={value}>{humanize(value, language)}</option>)}</select><span>{filtered.length} {text('records', 'سجلات')}</span></section><section className="ui3-surface ui3-register-surface"><CapaTable />{!loading && !filtered.length ? <EmptyCapa title={text('No CAPAs match the filters', 'لا توجد إجراءات تطابق عوامل التصفية')} /> : null}</section></div> : null}

    {screen === 'detail' && selected ? <div className="ui4-screen" data-testid="ui4-capa-detail"><button type="button" className="ui3-back-button" onClick={() => setScreen('register')}><ArrowLeft size={16} />{text('CAPA register', 'سجل الإجراءات')}</button><header className="ui3-record-header"><div><span className="ui3-eyebrow">{selected.capa_code || 'CAPA'}</span><h1>{selected.capa_title}</h1><p>{selected.capa_description || text('No problem statement recorded.', 'لم يتم تسجيل بيان للمشكلة.')}</p><div className="ui3-record-tags"><span className={`ui3-pill ui3-tone--${ui4CapaStatusTone(selected.capa_status)}`}>{humanize(selected.capa_status, language)}</span><span>{humanize(selected.capa_type, language)}</span><span>{capaSourceLabel(selected.source_type)}</span></div></div><div className="ui3-header-actions">{canManage ? <button type="button" className="ui3-secondary-button" onClick={() => setDecision({ action: 'refresh_inheritance', capa: selected })}><RefreshCw size={15} />{text('Refresh source links', 'تحديث روابط المصدر')}</button> : null}{canManage ? <button type="button" className="ui3-primary-button" onClick={() => setDecision({ action: 'create_item', capa: selected })}><Plus size={15} />{text('Add action', 'إضافة إجراء')}</button> : null}</div></header><section className="ui4-action-strip">{canManage ? <><button type="button" onClick={() => setDecision({ action: 'assign', capa: selected })}>{text('Assign', 'إسناد')}</button><button type="button" onClick={() => setDecision({ action: 'submit_plan', capa: selected })}>{text('Submit plan', 'إرسال الخطة')}</button><button type="button" onClick={() => setDecision({ action: 'submit_completion', capa: selected })}>{text('Submit completion', 'إرسال الإكمال')}</button></> : null}{canReview ? <><button type="button" onClick={() => setDecision({ action: 'approve_plan', capa: selected })}>{text('Approve plan', 'اعتماد الخطة')}</button><button type="button" onClick={() => setDecision({ action: 'validate_completion', capa: selected })}>{text('Validate completion', 'التحقق من الإكمال')}</button></> : null}<button type="button" onClick={() => setScreen('closure')}>{text('Closure gate', 'بوابة الإغلاق')}</button></section><div className="ui3-detail-layout"><main className="ui3-stack"><section className="ui3-surface"><div className="ui3-section-heading"><div><span>{text('Overview', 'نظرة عامة')}</span><h2>{text('CAPA details', 'تفاصيل الإجراء')}</h2></div><FileCheck2 size={20} /></div><div className="ui3-data-grid"><div><span>{text('Source', 'المصدر')}</span><strong>{capaSourceLabel(selected.source_type)} · {selected.source_reference || text('No reference', 'لا يوجد مرجع')}</strong></div><div><span>{text('Department', 'الإدارة')}</span><strong>{selected.department_name || text('Not assigned', 'غير مسندة')}</strong></div><div><span>{text('Owner', 'المالك')}</span><strong>{selected.capa_owner_name || text('Not assigned', 'غير مسند')}</strong></div><div><span>{text('Due date', 'تاريخ الاستحقاق')}</span><strong>{formatDate(selected.due_date)}</strong></div><div><span>{text('Root cause', 'السبب الجذري')}</span><strong>{selected.root_cause_summary || text('Pending analysis', 'التحليل معلق')}</strong></div><div><span>{text('Progress', 'التقدم')}</span><strong>{ui4CapaProgress(selected)}%</strong></div></div></section><GovernanceCriteriaLinkage source={{ type: 'capa', id: selected.id, organizationId: selected.organization_id, sourceDate: selected.created_at, departmentId: selected.department_id }} mode="capa" title={text('Source inheritance and supplemental criteria', 'وراثة المصدر والمعايير الإضافية')} canSuggest={canManage} canReview={canReview} onLinksChange={setGovernanceLinks} /></main><aside className="ui3-stack"><section className="ui3-surface"><div className="ui3-section-heading"><div><span>{text('Progress', 'التقدم')}</span><h2>{text('Lifecycle completion', 'إكمال دورة الحياة')}</h2></div><Gauge size={20} /></div><div className="ui4-progress-ring" style={{ '--ui4-progress': `${ui4CapaProgress(selected) * 3.6}deg` } as CSSProperties}><strong>{ui4CapaProgress(selected)}%</strong></div><div className="ui3-stat-list"><div><span>{text('Action items', 'بنود الإجراء')}</span><strong>{selected.completed_action_item_count}/{selected.action_item_count}</strong></div><div><span>{text('Evidence', 'الأدلة')}</span><strong>{humanize(selected.evidence_gate_status || 'pending', language)}</strong></div><div><span>{text('Effectiveness', 'الفعالية')}</span><strong>{humanize(selected.effectiveness_review_status || 'pending', language)}</strong></div></div></section></aside></div></div> : null}

    {screen === 'plan' && selected ? <div className="ui4-screen" data-testid="ui4-capa-plan"><header className="ui3-record-header ui4-compact-record"><div><span className="ui3-eyebrow">{selected.capa_code} · {text('Plan', 'الخطة')}</span><h1>{selected.capa_title}</h1><p>{text('Approved action plan with accountable owners, target dates, and evidence requirements.', 'خطة إجراء معتمدة بمالكين مسؤولين وتواريخ مستهدفة ومتطلبات أدلة.')}</p></div>{canManage ? <button type="button" className="ui3-primary-button" onClick={() => setDecision({ action: 'create_item', capa: selected })}><Plus size={15} />{text('Add action', 'إضافة إجراء')}</button> : null}</header><div className="ui4-stepper"><span className="active">1<small>{text('Plan', 'الخطة')}</small></span><span>2<small>{text('Implementation', 'التنفيذ')}</small></span><span>3<small>{text('Verification', 'التحقق')}</small></span><span>4<small>{text('Closure', 'الإغلاق')}</small></span></div><section className="ui3-surface ui3-register-surface"><div className="ui3-data-table ui4-action-table"><div className="ui3-table-head"><span>#</span><span>{text('Action', 'الإجراء')}</span><span>{text('Responsible', 'المسؤول')}</span><span>{text('Target date', 'التاريخ المستهدف')}</span><span>{text('Evidence', 'الأدلة')}</span><span>{text('Status', 'الحالة')}</span><span /></div>{detail.actions.map((item, index) => <button type="button" className="ui3-table-row" key={item.id} onClick={() => setDecision({ action: 'update_item', capa: selected, item })}><span>{index + 1}</span><span><strong>{item.action_item_title}</strong><small>{item.action_item_description || text('No description', 'لا يوجد وصف')}</small></span><span>{profiles.data?.find((profile) => profile.id === item.action_owner_id)?.full_name_en || text('Unassigned', 'غير مسند')}</span><span>{formatDate(item.due_date)}</span><span>{item.evidence_required ? text('Required', 'مطلوب') : text('Not required', 'غير مطلوب')}</span><span><StatusBadge status={humanize(item.status, language)} /></span><span><Eye size={15} /></span></button>)}</div>{!detail.actions.length ? <EmptyCapa title={text('No action items', 'لا توجد بنود إجراء')} detail={text('Add accountable actions before submitting the plan.', 'أضف إجراءات خاضعة للمساءلة قبل إرسال الخطة.')} /> : null}</section><div className="ui3-form-actions">{canReview ? <button type="button" className="ui3-secondary-button" onClick={() => setDecision({ action: 'reject_plan', capa: selected })}>{text('Return plan', 'إعادة الخطة')}</button> : null}{canManage ? <button type="button" className="ui3-primary-button" onClick={() => setDecision({ action: 'submit_plan', capa: selected })}>{text('Submit plan', 'إرسال الخطة')}</button> : null}{canReview ? <button type="button" className="ui3-primary-button" onClick={() => setDecision({ action: 'approve_plan', capa: selected })}>{text('Approve plan', 'اعتماد الخطة')}</button> : null}</div></div> : null}

    {screen === 'implementation' && selected ? <div className="ui4-screen" data-testid="ui4-capa-implementation"><header className="ui3-record-header ui4-compact-record"><div><span className="ui3-eyebrow">{selected.capa_code} · {text('Implementation', 'التنفيذ')}</span><h1>{selected.capa_title}</h1><p>{text('Action execution and evidence-backed progress.', 'تنفيذ الإجراءات والتقدم المدعوم بالأدلة.')}</p></div></header><div className="ui3-kpi-grid"><article><span>{text('Actions', 'الإجراءات')}</span><strong>{detail.actions.length}</strong></article><article className="ui3-tone--success"><span>{text('Completed', 'مكتملة')}</span><strong>{detail.actions.filter((item) => item.status === 'completed').length}</strong></article><article className="ui3-tone--warning"><span>{text('In progress', 'قيد التنفيذ')}</span><strong>{detail.actions.filter((item) => item.status === 'in_progress').length}</strong></article><article className="ui3-tone--danger"><span>{text('Blocked', 'محظورة')}</span><strong>{detail.actions.filter((item) => item.status === 'blocked').length}</strong></article></div><section className="ui3-surface"><div className="ui3-section-heading"><div><span>{text('Implementation progress', 'تقدم التنفيذ')}</span><h2>{ui4CapaProgress(selected)}%</h2></div><TrendingUp size={20} /></div><div className="ui4-linear-progress"><i style={{ width: `${ui4CapaProgress(selected)}%` }} /></div><div className="ui3-record-list">{detail.actions.map((item) => <button type="button" key={item.id} onClick={() => setDecision({ action: 'update_item', capa: selected, item })}><span><strong>{item.action_item_title}</strong><small>{formatDate(item.due_date)} · {item.progress_percent}%</small></span><StatusBadge status={humanize(item.status, language)} /></button>)}</div></section><div className="ui3-form-actions">{canManage ? <button type="button" className="ui3-primary-button" onClick={() => setDecision({ action: 'submit_completion', capa: selected })}>{text('Submit completion', 'إرسال الإكمال')}</button> : null}</div></div> : null}

    {screen === 'verification' && selected ? <div className="ui4-screen" data-testid="ui4-capa-verification"><header className="ui3-record-header ui4-compact-record"><div><span className="ui3-eyebrow">{selected.capa_code} · {text('Verification', 'التحقق')}</span><h1>{text('Verification & effectiveness', 'التحقق والفعالية')}</h1><p>{text('Independent completion validation and post-implementation effectiveness review.', 'التحقق المستقل من الإكمال ومراجعة الفعالية بعد التنفيذ.')}</p></div></header><div className="ui4-stepper"><span className="active">1<small>{text('Plan', 'الخطة')}</small></span><span className="active">2<small>{text('Implementation', 'التنفيذ')}</small></span><span className="active">3<small>{text('Verification', 'التحقق')}</small></span><span>4<small>{text('Closure', 'الإغلاق')}</small></span></div><div className="ui3-detail-layout"><main className="ui3-stack"><section className="ui3-surface"><div className="ui3-section-heading"><div><span>{text('Validation', 'التحقق')}</span><h2>{text('Completion review', 'مراجعة الإكمال')}</h2></div><ShieldCheck size={20} /></div><div className="ui3-data-grid"><div><span>{text('Validation status', 'حالة التحقق')}</span><strong>{humanize(selected.validation_status || 'pending', language)}</strong></div><div><span>{text('Evidence gate', 'بوابة الأدلة')}</span><strong>{humanize(selected.evidence_gate_status || 'pending', language)}</strong></div></div>{canReview ? <div className="ui3-form-actions"><button type="button" className="ui3-secondary-button" onClick={() => setDecision({ action: 'reject_completion', capa: selected })}>{text('Reject completion', 'رفض الإكمال')}</button><button type="button" className="ui3-primary-button" onClick={() => setDecision({ action: 'validate_completion', capa: selected })}>{text('Validate completion', 'التحقق من الإكمال')}</button></div> : null}</section><section className="ui3-surface"><div className="ui3-section-heading"><div><span>{text('Effectiveness reviews', 'مراجعات الفعالية')}</span><h2>{text('Verification history', 'سجل التحقق')}</h2></div><CheckCircle2 size={20} /></div>{detail.effectivenessReviews.length ? <ol className="ui3-timeline">{detail.effectivenessReviews.map((review) => <li key={review.id}><span /><div><strong>{humanize(review.review_result, language)}</strong><p>{review.review_method || text('No method recorded.', 'لم تسجل طريقة.')}</p><small>{formatDate(review.review_due_date)} · {review.review_note || text('Pending conclusion', 'الاستنتاج معلق')}</small></div></li>)}</ol> : <EmptyCapa title={text('No effectiveness review started', 'لم تبدأ مراجعة الفعالية')} />}</section></main><aside className="ui3-stack"><section className="ui3-surface"><div className="ui3-section-heading"><div><span>{text('Effectiveness', 'الفعالية')}</span><h2>{humanize(selected.effectiveness_review_status || 'pending', language)}</h2></div><Gauge size={20} /></div>{canReview ? <div className="ui3-form-actions"><button type="button" className="ui3-secondary-button" onClick={() => setDecision({ action: 'start_effectiveness', capa: selected })}>{text('Start review', 'بدء المراجعة')}</button><button type="button" className="ui3-primary-button" disabled={!detail.effectivenessReviews.length} onClick={() => setDecision({ action: 'complete_effectiveness', capa: selected })}>{text('Record result', 'تسجيل النتيجة')}</button></div> : null}</section></aside></div></div> : null}

    {screen === 'closure' && selected ? <div className="ui4-screen" data-testid="ui4-capa-closure"><header className="ui3-record-header ui4-compact-record"><div><span className="ui3-eyebrow">{selected.capa_code} · {text('Closure', 'الإغلاق')}</span><h1>{text('CAPA closure', 'إغلاق الإجراء التصحيحي')}</h1><p>{text('Closure is permitted only after action, evidence, validation, and effectiveness gates pass.', 'لا يسمح بالإغلاق إلا بعد اجتياز بوابات الإجراءات والأدلة والتحقق والفعالية.')}</p></div></header><div className="ui4-stepper"><span className="active">1<small>{text('Plan', 'الخطة')}</small></span><span className="active">2<small>{text('Implementation', 'التنفيذ')}</small></span><span className="active">3<small>{text('Verification', 'التحقق')}</small></span><span className={closure.passed ? 'active' : ''}>4<small>{text('Closure', 'الإغلاق')}</small></span></div><div className="ui3-detail-layout"><main className="ui3-stack"><section className={`ui3-surface ui3-gate-summary ${closure.passed ? '' : 'ui3-gate-summary--blocked'}`}>{closure.passed ? <CheckCircle2 size={22} /> : <AlertTriangle size={22} />}<div><strong>{closure.passed ? text('Closure gate satisfied', 'تم استيفاء بوابة الإغلاق') : text('Closure blocked', 'الإغلاق محظور')}</strong><p>{closure.passed ? text('All Patch 28 closure criteria are satisfied.', 'تم استيفاء جميع معايير إغلاق Patch 28.') : closure.blockers.join(' ')}</p></div></section><section className="ui3-surface"><div className="ui3-section-heading"><div><span>{text('Closure summary', 'ملخص الإغلاق')}</span><h2>{text('Evidence-backed conclusion', 'استنتاج مدعوم بالأدلة')}</h2></div><FileCheck2 size={20} /></div><div className="ui3-data-grid"><div><span>{text('Action items', 'بنود الإجراء')}</span><strong>{detail.blocker?.has_incomplete_action_items ? text('Incomplete', 'غير مكتملة') : text('Complete', 'مكتملة')}</strong></div><div><span>{text('Evidence', 'الأدلة')}</span><strong>{detail.blocker?.has_evidence_blocker ? text('Blocked', 'محظورة') : text('Accepted', 'مقبولة')}</strong></div><div><span>{text('Validation', 'التحقق')}</span><strong>{detail.blocker?.has_validation_blocker ? text('Required', 'مطلوب') : text('Approved', 'معتمد')}</strong></div><div><span>{text('Effectiveness', 'الفعالية')}</span><strong>{detail.blocker?.has_effectiveness_blocker ? text('Pending', 'معلقة') : text('Passed', 'اجتازت')}</strong></div></div></section><section className="ui3-surface"><div className="ui3-section-heading"><div><span>{text('Document governance', 'حوكمة الوثائق')}</span><h2>{text('Review triggers', 'محفزات المراجعة')}</h2></div><FileText size={20} /></div><p className="ui3-supporting-copy">{text('When effectiveness evidence reveals an inadequate governed document, trigger the existing Policy/SOP review workflow.', 'عندما تكشف أدلة الفعالية عن وثيقة محكومة غير كافية، شغّل سير مراجعة السياسة أو الإجراء الحالي.')}</p><button type="button" className="ui3-secondary-button" disabled={!canReview || !governanceLinks.some((link) => link.target_document_id)} onClick={() => setDecision({ action: 'document_review', capa: selected })}>{text('Trigger document review', 'تشغيل مراجعة الوثيقة')}</button></section></main><aside className="ui3-stack"><section className="ui3-surface"><div className="ui3-section-heading"><div><span>{text('Closure decision', 'قرار الإغلاق')}</span><h2>{humanize(selected.capa_status, language)}</h2></div><ShieldCheck size={20} /></div><div className="ui3-form-actions">{canManage ? <button type="button" className="ui3-secondary-button" onClick={() => setDecision({ action: 'request_closure', capa: selected })}>{text('Request closure', 'طلب الإغلاق')}</button> : null}{canReview ? <button type="button" className="ui3-primary-button" disabled={!closure.passed} onClick={() => setDecision({ action: 'approve_closure', capa: selected })}>{text('Approve closure', 'اعتماد الإغلاق')}</button> : null}{canReview ? <button type="button" className="ui3-secondary-button" onClick={() => setDecision({ action: 'reject_closure', capa: selected })}>{text('Return', 'إعادة')}</button> : null}</div>{selected.capa_status === 'closed' && canReview ? <button type="button" className="ui3-secondary-button" onClick={() => setDecision({ action: 'reopen', capa: selected })}>{text('Reopen with reason', 'إعادة الفتح مع السبب')}</button> : null}</section></aside></div></div> : null}

    {screen === 'report' && selected ? <div className="ui4-screen" data-testid="ui4-capa-report"><header className="ui3-record-header ui4-compact-record"><div><span className="ui3-eyebrow">{text('CAPA report', 'تقرير الإجراء التصحيحي')}</span><h1>{selected.capa_code} · {selected.capa_title}</h1><p>{text('Audit-ready lifecycle report sourced from the canonical Patch 28 record.', 'تقرير دورة حياة جاهز للتدقيق ومصدره سجل Patch 28 الأساسي.')}</p></div></header><div className="ui3-detail-layout"><main className="ui3-stack"><section className="ui3-surface"><div className="ui3-section-heading"><div><span>{text('Summary', 'الملخص')}</span><h2>{text('Corrective action conclusion', 'استنتاج الإجراء التصحيحي')}</h2></div><FileText size={20} /></div><div className="ui4-finding-narrative"><div><span>{text('Problem', 'المشكلة')}</span><p>{selected.capa_description || text('Not recorded', 'غير مسجلة')}</p></div><div><span>{text('Root cause', 'السبب الجذري')}</span><p>{selected.root_cause_summary || text('Not recorded', 'غير مسجل')}</p></div><div><span>{text('Corrective action', 'الإجراء التصحيحي')}</span><p>{selected.corrective_action_summary || text('See action plan.', 'راجع خطة الإجراء.')}</p></div><div><span>{text('Effectiveness', 'الفعالية')}</span><p>{humanize(selected.effectiveness_review_status || 'pending', language)}</p></div></div></section><section className="ui3-surface"><div className="ui3-section-heading"><div><span>{text('Audit trail', 'مسار التدقيق')}</span><h2>{text('Lifecycle events', 'أحداث دورة الحياة')}</h2></div><Clock3 size={20} /></div><ol className="ui3-timeline">{detail.events.map((event) => <li key={event.id}><span /><div><strong>{humanize(event.event_type, language)}</strong><p>{event.event_note || `${humanize(event.from_status || '', language)} → ${humanize(event.to_status || '', language)}`}</p><small>{formatDate(event.created_at)}</small></div></li>)}</ol></section></main><aside className="ui3-stack"><section className="ui3-surface"><div className="ui3-section-heading"><div><span>{text('Report metrics', 'مؤشرات التقرير')}</span><h2>{text('Readiness', 'الجاهزية')}</h2></div><BarChart3 size={20} /></div><div className="ui3-stat-list"><div><span>{text('Progress', 'التقدم')}</span><strong>{ui4CapaProgress(selected)}%</strong></div><div><span>{text('Actions', 'الإجراءات')}</span><strong>{selected.completed_action_item_count}/{selected.action_item_count}</strong></div><div><span>{text('Governance links', 'روابط الحوكمة')}</span><strong>{governanceLinks.length}</strong></div><div><span>{text('Events', 'الأحداث')}</span><strong>{detail.events.length}</strong></div></div></section></aside></div></div> : null}

    {screen === 'analytics' ? <div className="ui4-screen" data-testid="ui4-capa-analytics"><div className="ui3-kpi-grid"><article><span>{text('Closure rate', 'معدل الإغلاق')}</span><strong>{records.length ? Math.round((closed / records.length) * 100) : 0}%</strong><small>{text('Portfolio closed', 'المحفظة مغلقة')}</small></article><article className="ui3-tone--danger"><span>{text('Overdue rate', 'معدل التأخر')}</span><strong>{records.length ? Math.round((overdue / records.length) * 100) : 0}%</strong><small>{text('Outside due date', 'تجاوزت الاستحقاق')}</small></article><article><span>{text('Average progress', 'متوسط التقدم')}</span><strong>{records.length ? Math.round(records.reduce((sum, record) => sum + ui4CapaProgress(record), 0) / records.length) : 0}%</strong></article><article><span>{text('Repeat issues', 'مشكلات متكررة')}</span><strong>{records.filter((record) => record.repeat_issue_flag).length}</strong></article></div><div className="ui3-dashboard-grid"><section className="ui3-surface"><div className="ui3-section-heading"><div><span>{text('CAPA by priority', 'الإجراءات حسب الأولوية')}</span><h2>{text('Priority distribution', 'توزيع الأولوية')}</h2></div><BarChart3 size={20} /></div><div className="ui4-mini-bars">{prioritySummary.map((item) => <MiniBar key={item.priority} label={humanize(item.priority, language)} value={item.count} max={maxPriority} tone={item.priority === 'critical' || item.priority === 'high' ? 'danger' : item.priority === 'medium' ? 'warning' : 'success'} />)}</div></section><section className="ui3-surface"><div className="ui3-section-heading"><div><span>{text('CAPA by source', 'الإجراءات حسب المصدر')}</span><h2>{text('Source distribution', 'توزيع المصدر')}</h2></div><GitBranch size={20} /></div><div className="ui4-mini-bars">{sourceSummary.map((item) => <MiniBar key={item.source} label={capaSourceLabel(item.source)} value={item.count} max={maxSource} />)}</div></section><section className="ui3-surface ui3-span-all"><div className="ui3-section-heading"><div><span>{text('Cycle time', 'زمن الدورة')}</span><h2>{text('Progress distribution', 'توزيع التقدم')}</h2></div><TrendingUp size={20} /></div><div className="ui4-histogram">{[0,25,50,75,100].map((bucket) => <div key={bucket}><i style={{ height: `${Math.max(6, records.filter((record) => ui4CapaProgress(record) >= bucket && ui4CapaProgress(record) < bucket + 25).length * 18)}px` }} /><span>{bucket}-{bucket + 24}%</span></div>)}</div></section></div></div> : null}

    {screen === 'review' && selected ? <div className="ui4-screen" data-testid="ui4-capa-review"><header className="ui3-record-header ui4-compact-record"><div><span className="ui3-eyebrow">{text('Submit for review', 'إرسال للمراجعة')}</span><h1>{selected.capa_code} · {selected.capa_title}</h1><p>{text('Independent reviewers confirm the plan, completion, effectiveness, and closure evidence.', 'يؤكد المراجعون المستقلون الخطة والإكمال والفعالية وأدلة الإغلاق.')}</p></div></header><div className="ui4-stepper"><span className="active">1<small>{text('Plan', 'الخطة')}</small></span><span className={selected.completion_submitted_at ? 'active' : ''}>2<small>{text('Execute', 'تنفيذ')}</small></span><span className={selected.validation_status === 'approved' ? 'active' : ''}>3<small>{text('Validate', 'تحقق')}</small></span><span className={closure.passed ? 'active' : ''}>4<small>{text('Close', 'إغلاق')}</small></span><span className={selected.capa_status === 'closed' ? 'active' : ''}>5<small>{text('Review', 'مراجعة')}</small></span></div><div className="ui3-detail-layout"><main className="ui3-stack"><section className="ui3-surface"><div className="ui3-section-heading"><div><span>{text('Review readiness', 'جاهزية المراجعة')}</span><h2>{text('Governed checks', 'فحوصات محكومة')}</h2></div><ShieldCheck size={20} /></div><ul className="ui4-check-list"><li>{detail.actions.length} {text('action items retained', 'بنود إجراء محتفظ بها')}</li><li>{governanceLinks.filter((link) => link.inherited).length} {text('source-owned governance links inherited', 'روابط حوكمة مملوكة للمصدر وموروثة')}</li><li>{detail.effectivenessReviews.length} {text('effectiveness review records', 'سجلات مراجعة فعالية')}</li><li>{detail.events.length} {text('immutable lifecycle events', 'أحداث دورة حياة غير قابلة للتعديل')}</li></ul></section><section className="ui3-surface"><div className="ui3-section-heading"><div><span>{text('Reviewers', 'المراجعون')}</span><h2>{text('Independent approval path', 'مسار اعتماد مستقل')}</h2></div><ClipboardCheck size={20} /></div><div className="ui3-record-list ui3-record-list--static"><div><span><strong>{selected.reviewer_name || text('Primary reviewer', 'المراجع الرئيسي')}</strong><small>{text('Plan approval', 'اعتماد الخطة')}</small></span><StatusBadge status={selected.capa_status.includes('approved') ? text('Approved', 'معتمد') : text('Pending', 'قيد الانتظار')} /></div><div><span><strong>{text('Effectiveness reviewer', 'مراجع الفعالية')}</strong><small>{text('Validation and closure', 'التحقق والإغلاق')}</small></span><StatusBadge status={humanize(selected.effectiveness_review_status || 'pending', language)} /></div></div></section></main><aside className="ui3-stack"><section className="ui3-surface"><div className="ui3-section-heading"><div><span>{text('Review action', 'إجراء المراجعة')}</span><h2>{humanize(selected.capa_status, language)}</h2></div><CheckCircle2 size={20} /></div><div className="ui3-form-actions">{canManage ? <button type="button" className="ui3-secondary-button" onClick={() => setDecision({ action: 'submit_plan', capa: selected })}>{text('Submit plan', 'إرسال الخطة')}</button> : null}{canReview ? <button type="button" className="ui3-primary-button" onClick={() => setDecision({ action: 'approve_plan', capa: selected })}>{text('Approve plan', 'اعتماد الخطة')}</button> : null}</div></section></aside></div></div> : null}

    <GovernedDecisionDialog open={Boolean(decision)} title={decision ? humanize(decision.action, language) : ''} subtitle={decision?.capa ? `${decision.capa.capa_code || 'CAPA'} · ${decision.capa.capa_title}` : undefined} decisionVariant={decision?.action.startsWith('reject') || decision?.action === 'reopen' ? 'warning' : decision?.action.includes('approve') || decision?.action.includes('validate') ? 'approve' : 'action'} fields={decisionFields} isSubmitting={busy} submitDisabled={decision?.action === 'approve_closure' && !closure.passed} warningNotice={decision?.action === 'approve_closure' && !closure.passed ? closure.blockers.join(' ') : null} size={decision?.action === 'create' ? 'large' : 'medium'} onClose={() => setDecision(null)} onSubmit={executeDecision} />
  </section>;
}
